/**
 * Port for sending outbound email messages.
 *
 * <p>
 * Implementations delegate to the infrastructure mail layer (e.g. Quarkus Mailer).
 * </p>
 */
public interface SmtpMailSenderGateway {

  /**
   * Sends a mail using the default (globally configured) SMTP settings.
   *
   * @param mail the message to send
   */
  void send(OutboundMail mail);

  /**
   * Sends a mail using the provided SMTP configuration override. Used when a tenant has its own
   * SMTP settings.
   *
   * @param config tenant-specific SMTP configuration
   * @param mail the message to send
   */
  void send(MailConfiguration config, OutboundMail mail);
}
